	protected DataProvider read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created DataProvider" );

		DataProvider entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read DataProvider with primary key" );
		msg.append( dataProviderId );
		
		DataProviderFetchOneSummary fetchOneSummary = new DataProviderFetchOneSummary( dataProviderId );

		try {
			entity = DataProviderService.getDataProviderInstance().getDataProvider( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found DataProvider " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a DataProvider.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a DataProvider." );

		StringBuilder msg = new StringBuilder( "Failed to update a DataProvider : " );        
		DataProvider entity = read();
		UpdateDataProviderCommand command = generateUpdateCommand();
		command.setDataProviderId(entity.getDataProviderId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created DataProvider." );

			// for use later on...
			dataProviderId = entity.getDataProviderId();

			DataProviderService proxy = DataProviderService.getDataProviderInstance();  

			proxy.updateDataProvider( command ).get();

			LOGGER.info( "-- Successfully saved DataProvider - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + dataProviderId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a DataProvider.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created DataProvider." );

		DataProvider entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read DataProvider with id " + dataProviderId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read DataProvider with id " + dataProviderId );

			throw e;
		}

		try{
			DataProviderService.getDataProviderInstance().delete( new DeleteDataProviderCommand( entity.getDataProviderId() ) ).get();
			LOGGER.info( "-- Successfully deleted DataProvider with id " + dataProviderId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete DataProvider with id " + dataProviderId );

			throw e;
		}
	}

	/**
	 * get all DataProviders.
	 */
	protected List<DataProvider> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of DataProviders:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all DataProvider : " );        
		List<DataProvider> collection  = new ArrayList<>();

		try {
			// call the static get method on the DataProviderService
			collection = DataProviderService.getDataProviderInstance().getAllDataProvider();
			assertNotNull( collection, "An Empty collection of DataProvider was incorrectly returned.");
			
			// Now print out the values
			DataProvider entity = null;            
			Iterator<DataProvider> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getDataProviderId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

